list_variations.code:
use WebCommander\Resources\Variations\Variations;

$response = Variations::listVariations($client, ['search' => 'size', 'standard' => 'text']);

foreach ($response->map['variations'] as $variation) {
    echo $variation['id'], ' ', $variation['name'], ': ', implode(', ', array_column($variation['options'], 'label')), PHP_EOL;
}
echo $response->map['pagination']['has_next'] ? 'more pages' : 'last page', PHP_EOL;

create_variation.code:
use WebCommander\Resources\Variations\Variations;

$response = Variations::createVariation($client, ['variation' => [
    'name' => 'Shirt Size', 'standard' => 'text',
    'options' => [
        ['label' => 'Small', 'value' => 'S', 'order' => 1, 'default' => true],
        ['label' => 'Medium', 'value' => 'M', 'order' => 2],
    ],
]]);

$variation = $response->map['variation'];
echo $variation['id'], ': ', implode(', ', array_column($variation['options'], 'id')), PHP_EOL;

get_variation.code:
use WebCommander\Resources\Variations\Variations;

$response = Variations::getVariation($client, 12);

$variation = $response->map['variation'];
echo $variation['name'], ' (', $variation['standard'], ')', PHP_EOL;
foreach ($variation['options'] as $option) {
    echo $option['id'], ' ', $option['label'], $option['default'] ? ' (default)' : '', PHP_EOL;
}

update_variation.code:
use WebCommander\Resources\Variations\Variations;

$response = Variations::updateVariation($client, 15, ['variation' => [
    'name' => 'Shirt Size',
    'options' => [
        ['id' => 201, 'label' => 'Small', 'value' => 'S', 'order' => 1, 'default' => true],
        ['label' => 'Large', 'value' => 'L', 'order' => 3],
    ],
]]);

echo implode(', ', array_column($response->map['variation']['options'], 'label')), PHP_EOL;

patch_variation.code:
use WebCommander\Resources\Variations\Variations;

$response = Variations::patchVariation($client, 15, ['variation' => [
    'options' => [
        ['id' => 201, 'label' => 'Petite'],
        ['label' => 'Extra Large', 'value' => 'XL', 'order' => 4],
    ],
]]);

foreach ($response->map['variation']['options'] as $option) {
    echo $option['id'], ' ', $option['label'], PHP_EOL;
}

list_product_variations.code:
use WebCommander\Resources\Variations\Variations;

$response = Variations::listProductVariations($client, 4321);

foreach ($response->map['variations'] as $group) {
    foreach ($group['variants'] as $variant) {
        echo $variant['variation_id'], ' ', $variant['key'], ' ', $variant['pricing']['base_price'], ' ', $variant['inventory']['quantity'], PHP_EOL;
    }
}

import_product_variations.code:
use WebCommander\Resources\Variations\Variations;

$response = Variations::importProductVariations($client, 4321, ['variations' => [['product_key' => 'Size', 'variants' => [
    ['key' => 'Small', 'name' => 'Cotton T-Shirt Small', 'sku' => 'TSHIRT-001-S', 'pricing' => ['base_price' => 25.0]],
    ['key' => 'Medium', 'name' => 'Cotton T-Shirt Medium', 'sku' => 'TSHIRT-001-M', 'pricing' => ['base_price' => 25.0]],
]]]], transactionNo: 'IMPORT-2026-10-18');

echo $response->map['message'], ' (', $response->map['total_variants'], ' variants)', PHP_EOL;

update_product_variations.code:
use WebCommander\Resources\Variations\Variations;

$response = Variations::updateProductVariations($client, 4321, [
    'variation_ids' => [91], 'available' => true, 'available_stock' => 12,
    'min_order_quantity' => 1, 'max_order_quantity' => 5,
]);

echo $response->map['message'], PHP_EOL;
foreach ($response->map['updated'] as $variant) {
    echo $variant['id'], ' ', $variant['name'], PHP_EOL;
}
